', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/disclosure-widget--framework-react--style-modern/google/gemini-3-flash-preview__s3/script.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents='const { useState } = React;

const faqData = [
  {
    question: "Why do cats purr?",
    answer: "Cats purr for various reasons, including contentment, stress relief, and even to promote healing in their bones and tissues. It is a multi-purpose vibration that helps them communicate and self-soothe."
  },
  {
    question: "Why do cats have whiskers?",
    answer: "Whiskers are highly sensitive tactile organs. They help cats navigate in the dark, detect changes in air currents, and judge whether they can fit through tight spaces."
  },
  {
    question: "Why do cats love boxes?",
    answer: "Boxes provide a sense of security and a safe hiding spot from which cats can observe their surroundings. They also help maintain body heat, as cardboard is an excellent insulator."
  },
  {
    question: "How much do cats sleep?",
    answer: "On average, cats sleep between 12 to 16 hours a day. This is an evolutionary trait from their ancestors who needed to conserve energy for hunting bursts."
  },
  {
    question: "Do cats always land on their feet?",
    answer: "Not always, but they have a 'righting reflex' that allows them to twist their bodies in mid-air. However, the success of the landing depends on the height of the fall and the cat's physical condition."
  }
];

const FAQItem = ({ question, answer }) => {
  const [isOpen, setIsOpen] = useState(false);

  const toggle = () => setIsOpen(!isOpen);

  return (
    <div className="example">
      <h3>
        <button
          type="button"
          className="faq-trigger"
          onClick={toggle}
          aria-expanded={isOpen}
        >
          <span className="faq-question">{question}</span>
          <span className="faq-icon-wrapper">
            <svg
              className="faq-icon"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              aria-hidden="true"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 9l-7 7-7-7"
              />
            </svg>
          </span>
        </button>
      </h3>
      <div className="details" hidden={!isOpen}>
        <div className="details-content">
          <p>{answer}</p>
        </div>
      </div>
    </div>
  );
};

const App = () => {
  return (
    <div className="container">
      <header>
        <h1>Cat FAQ</h1>
        <p className="subtitle">Everything you ever wanted to know about our feline friends.</p>
      </header>
      <main id="main-content">
        <div className="faq-list">
          {faqData.map((item, index) => (
            <FAQItem key={index} question={item.question} answer={item.answer} />
          ))}
        </div>
      </main>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
