  --border-color: #e5e7eb;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--accent-color);
  color: white;
  padding: 8px;
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
  padding: 2rem 1rem;
}

.container {
  max-width: 600px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 3rem;
}

h1 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 0.5rem;
}

p.subtitle {
  color: var(--text-secondary);
  font-size: 1.125rem;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Requirement: Wrap each question/answer section in a div with class "example" */
.example {
  background: var(--white);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  overflow: hidden;
  transition: box-shadow 0.2s ease-in-out;
}

.example:hover {
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-primary);
  transition: background-color 0.2s;
}

.faq-trigger:focus {
  outline: 2px solid var(--accent-color);
  outline-offset: -2px;
}

.faq-trigger:hover {
  background-color: #f9fafb;
}

.faq-question {
  flex: 1;
}

.faq-icon-wrapper {
  margin-left: 1rem;
  display: flex;
  align-items: center;
}

.faq-icon {
  width: 1.25rem;
  height: 1.25rem;
  color: var(--text-secondary);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.faq-trigger[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
}

/* Requirement: Give the container for the controlled content a class of "details" */
.details {
  overflow: hidden;
}

.details-content {
  padding: 0 1.5rem 1.5rem;
  color: var(--text-secondary);
  font-size: 1rem;
  line-height: 1.6;
}

[hidden] {
  display: none !important;
}

footer {
  margin-top: 4rem;
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.875rem;
}

@media (max-width: 640px) {
  h1 {
    font-size: 1.875rem;
  }
}
