             </div>
           </div>
         </div>
       );
     };

     const App = () => {
       const year = new Date().getFullYear();
       return (
         <div className="container">
           <header>
             <h1>Cat FAQ</h1>
             <p className="subtitle">Everything you ever wanted to know about our feline friends.</p>
